import{_ as l,a0 as t,w as o,s as d,I as n,x as a,a1 as i,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 中使用舊相機作為網絡攝像頭 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用舊相機作為網絡攝像頭 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用舊相機作為網絡攝像頭 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用舊相機作為網絡攝像頭 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20221219.1 ⭐️⭐️ How I use my old camera as a webcam with Linux","title":"如何在 Linux 中使用舊相機作為網絡攝像頭","tag":"202303","desc":""},"relativePath":"202303/20221219.1 ⭐️⭐️ How I use my old camera as a webcam with Linux.md","filePath":"[post].md"}'),c={name:"202303/20221219.1 ⭐️⭐️ How I use my old camera as a webcam with Linux.md"};function h(u,s,g,b,k,m){const e=t("Link");return o(),d("div",null,[s[18]||(s[18]=n("h1",{id:"如何在-linux-中使用舊相機作為網絡攝像頭",tabindex:"-1"},[a("如何在 Linux 中使用舊相機作為網絡攝像頭 "),n("a",{class:"header-anchor",href:"#如何在-linux-中使用舊相機作為網絡攝像頭","aria-label":"Permalink to “如何在 Linux 中使用舊相機作為網絡攝像頭”"},"​")],-1)),s[19]||(s[19]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202303/21/233633z1qxdoq1shrx1xmc.jpg",alt:""})],-1)),s[20]||(s[20]=n("blockquote",null,[n("p",null,"我用 gphoto2 給我的舊單反相機帶來了新的生命，把它變成了 Linux 電腦的網絡攝像頭。")],-1)),s[21]||(s[21]=n("p",null,"今年，在我基本上放棄了 MacBook，轉而使用 NixOS 機器之後，我開始在與人進行視頻通話時被要求“打開攝像頭”。這是一個問題，因為我沒有網絡攝像頭。我考慮購買一個，但後來我意識到我有一台完好無損的 2008 年產的佳能 EOS Rebel XS 數碼單反相機放在書架上。這台相機有一個 mini-USB 接口，所以我自然而然地思考：一台數碼單反相機、一個 mini-USB 接口和一台台式電腦，是否意味着我能擁有一個網絡攝像頭？",-1)),s[22]||(s[22]=n("p",null,"只有一個問題。我的佳能 EOS Rebel XS 不能錄製視頻。它可以拍攝一些漂亮的照片，僅此而已。所以這結束了？",-1)),s[23]||(s[23]=n("p",null,"還是有別的辦法？",-1)),n("p",null,[s[1]||(s[1]=a("恰好有一個叫做 ",-1)),i(e,{href:"http://gphoto.org/"},{default:p(()=>[...s[0]||(s[0]=[a("gphoto2",-1)])]),_:1}),s[2]||(s[2]=a(" 的神奇的開源軟件。一旦安裝，它允許你從計算機控制各種支持的相機，並拍攝照片和視頻。",-1))]),s[24]||(s[24]=r(`<h3 id="支持的相機" tabindex="-1">支持的相機 <a class="header-anchor" href="#支持的相機" aria-label="Permalink to “支持的相機”">​</a></h3><p>首先，瞭解你的設備是否得到支持：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --list-cameras</span></span></code></pre></div><h3 id="拍攝圖像" tabindex="-1">拍攝圖像 <a class="header-anchor" href="#拍攝圖像" aria-label="Permalink to “拍攝圖像”">​</a></h3><p>你可以用它拍照：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --capture-image-and-download</span></span></code></pre></div><p>快門觸發，圖像會保存到你當前的工作目錄中。</p><h3 id="錄製視頻" tabindex="-1">錄製視頻 <a class="header-anchor" href="#錄製視頻" aria-label="Permalink to “錄製視頻”">​</a></h3><p>我意識到了這裏的潛力，所以儘管我的相機沒有視頻功能，我還是決定嘗試 <code>gphoto2 --capture-movie</code> 命令。不知怎麼，儘管我的相機不支持視頻功能，<code>gphoto2</code> 仍然能夠生成一個 MJPEG 文件！</p><p>在我的相機上，我需要將其置於“實時預覽”模式下，然後 <code>gphoto2</code> 才能錄製視頻。這包括將相機設置為縱向模式，然後按下 “<ruby>設置<rt>Set</rt></ruby>” 按鈕，使取景器關閉，相機屏幕顯示圖像。不幸的是，這還不足以將其用作網絡攝像頭。它仍然需要分配一個視頻設備，例如 <code>/dev/video0</code>。</p><h3 id="安裝-ffmpeg-和-v4l2loopback" tabindex="-1">安裝 ffmpeg 和 v4l2loopback <a class="header-anchor" href="#安裝-ffmpeg-和-v4l2loopback" aria-label="Permalink to “安裝 ffmpeg 和 v4l2loopback”">​</a></h3><p>毫不奇怪，有一個開源的解決方案來解決這個問題。首先，使用你的包管理器安裝 <code>gphoto2</code>、<code>ffmpeg</code> 和 <code>mpv</code>。例如，在 Fedora 、CentOS 、Mageia 和類似的 Linux 發行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install gphoto2 ffmpeg mpv</span></span></code></pre></div><p>在 Debian、Linux Mint 及其類似發行版:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install gphoto2 ffmpeg mpv</span></span></code></pre></div><p>我使用的是 NixOS，這是我的配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># configuration.nix</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>environment.systemPackages = with pkgs; [</span></span>
<span class="line"><span>  ffmpeg</span></span>
<span class="line"><span>  gphoto2</span></span>
<span class="line"><span>  mpv</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>創建虛擬視頻設備需要使用 <code>v4l2loopback</code> Linux 內核模組。在撰寫本文時，該功能未包含在主線內核中，因此你需要自己下載和編譯它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/umlaeute/v4l2loopback</span></span>
<span class="line"><span>$ cd v4l2loopback</span></span>
<span class="line"><span>$ make</span></span>
<span class="line"><span>$ sudo make install</span></span>
<span class="line"><span>$ sudo depmod -a</span></span></code></pre></div><p>如果你像我一樣使用 NixOS ，你可以在 <code>configuration.nix</code> 中添加額外的模組包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[...]</span></span>
<span class="line"><span>boot.extraModulePackages = with config.boot.kernelPackages;</span></span>
<span class="line"><span>[ v4l2loopback.out ];</span></span>
<span class="line"><span>boot.kernelModules = [</span></span>
<span class="line"><span>  &quot;v4l2loopback&quot;</span></span>
<span class="line"><span>];</span></span>
<span class="line"><span>boot.extraModprobeConfig = &#39;&#39;</span></span>
<span class="line"><span>  options v4l2loopback exclusive_caps=1 card_label=&quot;Virtual Camera&quot;</span></span>
<span class="line"><span>&#39;&#39;;</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>在 NixOS 上, 運行 <code>sudo nixos-rebuild switch</code>，然後重啓。</p><h3 id="創建一個視頻設備" tabindex="-1">創建一個視頻設備 <a class="header-anchor" href="#創建一個視頻設備" aria-label="Permalink to “創建一個視頻設備”">​</a></h3><p>假設你的計算機當前沒有 <code>/dev/video</code> 設備，你可以藉助 <code>v4l2loopback</code> 在需要時創建一個。</p><p>運行以下命令，將 <code>gphoto2</code> 中的數據發送到 <code>ffmpeg</code>，使用設備如 <code>/dev/video0</code> 設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --stdout --capture-movie |</span></span>
<span class="line"><span> ffmpeg -i - -vcodec rawvideo -pix_fmt yuv420p -f v4l2 /dev/video0</span></span></code></pre></div><p>你得到的輸出是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ffmpeg version 4.4.1 Copyright (c) 2000-2021 the FFmpeg developers</span></span>
<span class="line"><span>  built with gcc 11.3.0 (GCC)</span></span>
<span class="line"><span>  configuration: --disable-static ...</span></span>
<span class="line"><span>  libavutil      56. 70.100 / 56. 70.100</span></span>
<span class="line"><span>  libavcodec     58.134.100 / 58.134.100</span></span>
<span class="line"><span>  libavformat    58. 76.100 / 58. 76.100</span></span>
<span class="line"><span>  libavdevice    58. 13.100 / 58. 13.100</span></span>
<span class="line"><span>  libavfilter     7.110.100 /  7.110.100</span></span>
<span class="line"><span>  libavresample   4.  0.  0 /  4.  0.  0</span></span>
<span class="line"><span>  libswscale      5.  9.100 /  5.  9.100</span></span>
<span class="line"><span>  libswresample   3.  9.100 /  3.  9.100</span></span>
<span class="line"><span>  libpostproc    55.  9.100 / 55.  9.100</span></span>
<span class="line"><span>Capturing preview frames as movie to &#39;stdout&#39;. Press Ctrl-C to abort.[mjpeg @ 0x1dd0380] Format mjpeg detected only with low score of 25, misdetection possible!</span></span>
<span class="line"><span>Input #0, mjpeg, from &#39;pipe:&#39;:</span></span>
<span class="line"><span>  Duration: N/A, bitrate: N/A</span></span>
<span class="line"><span>  Stream #0:0: Video: mjpeg (Baseline), yuvj422p(pc, bt470bg/unknown/unknown), 768x512 ...</span></span>
<span class="line"><span>Stream mapping:</span></span>
<span class="line"><span>  Stream #0:0 -&gt; #0:0 (mjpeg (native) -&gt; rawvideo (native))[swscaler @ 0x1e27340] deprecated pixel format used, make sure you did set range correctly</span></span>
<span class="line"><span>Output #0, video4linux2,v4l2, to &#39;/dev/video0&#39;:</span></span>
<span class="line"><span>  Metadata:</span></span>
<span class="line"><span>    encoder         : Lavf58.76.100</span></span>
<span class="line"><span>  Stream #0:0: Video: rawvideo (I420 / 0x30323449) ...</span></span>
<span class="line"><span>    Metadata:</span></span>
<span class="line"><span>      encoder         : Lavc58.134.100 rawvideoframe=  289 fps= 23 q=-0.0 size=N/A time=00:00:11.56 bitrate=N/A speed=0.907x</span></span></code></pre></div><p>要查看來自網絡攝像頭的視頻，請使用 <code>mpv</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mpv av://v4l2:/dev/video0 --profile=low-latency --untimed</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/2022-12/streaming-webcam.png" alt="Streaming a live feed from the webcam"></p><h3 id="自動啓動你的網絡攝像頭" tabindex="-1">自動啓動你的網絡攝像頭 <a class="header-anchor" href="#自動啓動你的網絡攝像頭" aria-label="Permalink to “自動啓動你的網絡攝像頭”">​</a></h3><p>每次想使用網絡攝像頭時都需要執行一次命令有點麻煩。幸運的是，你可以在啓動時自動運行此命令。我將其實現為一個 <code>systemd</code> 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># configuration.nix</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>  systemd.services.webcam = {</span></span>
<span class="line"><span>    enable = true;</span></span>
<span class="line"><span>    script = &#39;&#39;</span></span>
<span class="line"><span>      \${pkgs.gphoto2}/bin/gphoto2 --stdout --capture-movie |</span></span>
<span class="line"><span>        \${pkgs.ffmpeg}/bin/ffmpeg -i - \\</span></span>
<span class="line"><span>            -vcodec rawvideo -pix_fmt yuv420p -f v4l2  /dev/video0</span></span>
<span class="line"><span>    &#39;&#39;;</span></span>
<span class="line"><span>wantedBy = [ &quot;multi-user.target&quot; ];</span></span>
<span class="line"><span>  };</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>在 NixOS 上，運行 <code>sudo nixos-rebuild switch</code>，然後重新啓動你的計算機。你的網絡攝像頭已經開啓並處於活動狀態。</p><p>要檢查是否存在任何問題，可以使用 <code>systemctl status webcam</code> 命令。它會告訴你服務最後一次運行的時間，並提供其以前輸出的日誌。這對於調試非常有用。</p><h3 id="迭代以使其變得更好" tabindex="-1">迭代以使其變得更好 <a class="header-anchor" href="#迭代以使其變得更好" aria-label="Permalink to “迭代以使其變得更好”">​</a></h3><p>止步於此也許很誘人。但是，考慮到當前的全球危機，我們可能需要思考是否有必要一直開着網絡攝像頭。這讓我感到不太理想，原因如下：</p><ul><li>這浪費電。</li><li>這類事情涉及隱私問題。</li></ul><p>我的攝像頭有一個鏡頭蓋，所以説實話，第二個原因並不真的讓我感到困擾。當我不使用網絡攝像頭時，我總是可以把鏡頭蓋上。然而，讓一個耗電量大的單反相機整天開着（更不用説需要解碼視頻所需的 CPU 開銷），對我的電費並沒有任何好處。</p><p>理想情況是：</p><ul><li>我一直把相機插在電腦上，但是關閉的。</li><li>當我想使用網絡攝像頭時，我按下相機的電源按鈕將其打開。</li><li>我的計算機會檢測到相機並啓動 systemd 服務。</li><li>使用網絡攝像頭完成後，我再次將其關閉。</li></ul><p>為了實現這一點，你需要使用一個自定義的 udev 規則。</p><p>udev 規則可以告訴你的計算機，當它發現某個設備已經可用時執行某個任務。這可以是外部硬盤甚至是非 USB 設備。在這種情況下，你需要通過其 USB 連接識別相機。</p><p>首先，指定 udev 規則被觸發時要運行的命令。你可以用一個 shell 腳本來完成（<code>systemctl restart webcam</code> 應該可以工作）。我運行的是 NixOS，所以我只需要創建一個派生包（一個 Nix 包），它會重新啓動 systemd 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># start-webcam.nix</span></span>
<span class="line"><span>with import &lt;nixpkgs&gt; { };</span></span>
<span class="line"><span>writeShellScriptBin &quot;start-webcam&quot; &#39;&#39;</span></span>
<span class="line"><span>  systemctl restart webcam</span></span>
<span class="line"><span>  # debugging example</span></span>
<span class="line"><span>  # echo &quot;hello&quot; &amp;&gt; /home/tom/myfile.txt</span></span>
<span class="line"><span>  # If myfile.txt gets created then we know the udev rule has triggered properly&#39;&#39;</span></span></code></pre></div><p>接下來，實際定義 udev 規則。查找攝像頭的設備和廠商 ID。使用 <code>lsusb</code> 命令可以完成此操作。該命令可能已經安裝在你的發行版上，但我不經常使用它，因此我只需要根據需要使用 <code>nix-shell</code> 安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nix-shell -p usbutils</span></span></code></pre></div><p>無論你的計算機上已經安裝了它，還是剛剛安裝，請運行 <code>lsusb</code> ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsusb</span></span>
<span class="line"><span>Bus 002 Device 008: ID 04a9:317b Canon, Inc. Canon Digital Camera[...]</span></span></code></pre></div><p>在此輸出中，廠商 ID 為 <code>04a9</code>，設備 ID 為 <code>317b</code>。這已足以創建 udev 規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ACTION==&quot;add&quot;, SUBSYSTEM==&quot;usb&quot;,</span></span>
<span class="line"><span>ATTR{idVendor}==&quot;04a9&quot;,</span></span>
<span class="line"><span>ATTR{idProduct}==&quot;317b&quot;,</span></span>
<span class="line"><span>RUN+=&quot;/usr/local/bin/start-webcam.sh&quot;</span></span></code></pre></div><p>或者，如果你使用的是 NixOS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># configuration.nix[...]let</span></span>
<span class="line"><span>  startWebcam = import ./start-webcam.nix;[...]</span></span>
<span class="line"><span>services.udev.extraRules = &#39;&#39;</span></span>
<span class="line"><span>  ACTION==&quot;add&quot;,  \\</span></span>
<span class="line"><span>  SUBSYSTEM==&quot;usb&quot;, \\</span></span>
<span class="line"><span>  ATTR{idVendor}==&quot;04a9&quot;, \\</span></span>
<span class="line"><span>  ATTR{idProduct}==&quot;317b&quot;,  \\</span></span>
<span class="line"><span>  RUN+=&quot;\${startWebcam}/bin/start-webcam&quot;&#39;&#39;;[...]</span></span></code></pre></div><p>最後，在你的 <code>start-webcam</code> systemd 服務中刪除 <code>wantedBy = [&quot;multi-user.target&quot;];</code> 這一行。（如果保留它，則無論相機是否開啓，該服務都會在下次重啓時自動啓動。）</p><h3 id="重複使用舊技術" tabindex="-1">重複使用舊技術 <a class="header-anchor" href="#重複使用舊技術" aria-label="Permalink to “重複使用舊技術”">​</a></h3><p>我希望這篇文章能讓你在放棄一些舊技術之前三思而後行。Linux 可以為技術注入活力，無論是你的電腦還是數碼相機或其他外圍設備等簡單的東西。</p><hr>`,58)),n("p",null,[s[4]||(s[4]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/22/12/old-camera-webcam-linux"},{default:p(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/22/12/old-camera-webcam-linux",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/tomoliver"},{default:p(()=>[...s[5]||(s[5]=[a("Tom Oliver",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),i(e,{href:"https://github.com/lkxed"},{default:p(()=>[...s[6]||(s[6]=[a("lkxed",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),i(e,{href:"https://github.com/Pabloxllwe"},{default:p(()=>[...s[7]||(s[7]=[a("Pabloxllwe",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const y=l(c,[["render",h]]);export{x as __pageData,y as default};
